// Appiattisce (una Pagina per item) -> Moduli -> Lead e normalizza
const out = [];
for (const it of $input.all()) {
  const page = it.json || {};
  const pageId = page.id;
  const forms = (page.leadgen_forms && page.leadgen_forms.data) || [];
  for (const form of forms) {
    const leads = (form.leads && form.leads.data) || [];
    for (const lead of leads) {
      const flat = {};
      for (const f of (lead.field_data || [])) {
        const val = Array.isArray(f.values) ? f.values[0] : f.value;
        flat[String(f.name || '').toLowerCase()] = val;
      }
      const pick = (terms) => {
        for (const k of Object.keys(flat)) {
          if (terms.some((t) => k.includes(t))) {
            const v = flat[k];
            if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
          }
        }
        return null;
      };
      const full = pick(['full name', 'nome e cognome', 'nome completo', 'nome', 'name']);
      const first = pick(['first', 'nome']);
      const last = pick(['last', 'cognome']);
      const name = full || [first, last].filter(Boolean).join(' ') || null;
      const phone = pick(['phone', 'telefono', 'cellulare', 'numero']);
      const email = pick(['email', 'e-mail', 'mail']);
      out.push({ json: { page_id: pageId, page_name: page.name, form_id: form.id, name, phone, email, created_time: lead.created_time } });
    }
  }
}
return out;
